// Finds past customers who have gone quiet. Days since "Last Visit" decide the stage (30, 60, 90 by default);
// each stage is sent once per absence, and a new visit starts the count again.
const s = $('Your Settings').first().json;
const stages = String(s.winBackDays || '30,60,90').split(',').map(x => parseInt(String(x).trim(), 10)).filter(n => n > 0).sort((a, b) => a - b);
const cap = Math.max(1, Math.min(200, parseInt(s.dailyLimit, 10) || 20));
const today = $now.toFormat('yyyy-MM-dd');
const emailOk = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
const toISO = (v) => {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  const t = String(v).trim();
  const m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  const p = Date.parse(t);
  if (isNaN(p)) return '';
  const d = new Date(p);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const due = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.row_number) continue;
  const email = String(r['Email'] || '').trim().toLowerCase();
  const status = String(r['Status'] || '').trim().toLowerCase();
  const lastVisit = toISO(r['Last Visit']);
  const lastMessage = toISO(r['Last Message']);
  if (!emailOk(email) || !lastVisit) continue;
  if (['stop', 'unsubscribed'].includes(status)) continue;          // they asked us to stop: never again
  const sameAbsence = lastMessage && lastMessage >= lastVisit;       // our last message was after their last visit
  if (status === 'replied' && sameAbsence) continue;                 // they answered: the owner takes it from here
  const sent = sameAbsence ? (parseInt(r['Win-back Stage'], 10) || 0) : 0;
  const away = daysBetween(lastVisit, today);
  const reached = stages.filter(d => away >= d);
  if (!reached.length) continue;
  const stage = reached[reached.length - 1];                         // send the most fitting one, never several at once
  if (stage <= sent) continue;
  due.push({
    row_number: r.row_number, name: String(r['Name'] || '').trim(), email, lastVisit, daysAway: away,
    lastService: String(r['Last Service'] || '').trim(), stage, stageIndex: stages.indexOf(stage),
    isLast: stage === stages[stages.length - 1], contacted: sent > 0, lastContacted: sameAbsence ? lastMessage : '', today,
    prevStage: String(r['Win-back Stage'] ?? ''), prevLastMessage: String(r['Last Message'] || ''),   // to undo a failed send
  });
  if (due.length >= cap) break;
}
if (!due.length) return [];
const replyQuery = 'from:(' + due.map(d => d.email).join(' OR ') + ') newer_than:120d';
return due.map(d => ({ json: { ...d, replyQuery } }));

// Joins the inbox search to the due leads: a lead has replied if a message FROM their exact address arrived
// after we last emailed them. "STOP" style replies are treated as an opt-out.
const due = $('Find Quiet Customers').all().map(i => i.json);
const msgs = $input.all().map(i => i.json).filter(m => m && Object.keys(m).length);
const addrs = (v) => ((typeof v === 'string' ? v : JSON.stringify(v || '')).toLowerCase().match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/g) || []);
const fromOf = (m) => {
  if (m.From !== undefined) return addrs(m.From);
  if (m.from !== undefined) return addrs(m.from);
  const h = ((m.payload && m.payload.headers) || []).find(x => String(x.name).toLowerCase() === 'from');
  return addrs(h ? h.value : '');
};
const timeOf = (m) => { if (m.internalDate) return Number(m.internalDate); const t = Date.parse(m.date || m.Date || ''); return isNaN(t) ? NaN : t; };
const textOf = (m) => String(m.snippet || m.text || '').replace(/\s+/g, ' ').trim();
const stopWords = /^\s*(stop|unsubscribe|remove me|opt out|opt-out)\b/i;
return due.map(l => {
  const since = l.lastContacted ? Date.parse(l.lastContacted + 'T00:00:00Z') - 86400000 : NaN;  // a day of slack for time zones
  const hits = l.contacted ? msgs.filter(m => fromOf(m).includes(l.email) && (isNaN(timeOf(m)) || isNaN(since) || timeOf(m) >= since)) : [];
  hits.sort((a, b) => (timeOf(b) || 0) - (timeOf(a) || 0));
  const snippet = hits[0] ? textOf(hits[0]).slice(0, 300) : '';
  return { json: { ...l, replied: hits.length > 0, optOut: hits.length > 0 && stopWords.test(snippet), replySnippet: snippet } };
});

