// Turns the AI draft (or a ready-made template if AI is off or fails) into the email, and works out what to
// write back to the sheet. Runs once per customer.
const s = $('Your Settings').first().json;
const c = $('Match Replies').item.json;
const first = (c.name.split(/\s+/)[0] || 'there');
const you = String(s.yourName || '').trim() || 'The team';
const biz = String(s.businessName || '').trim() || 'us';
const service = c.lastService || 'your last visit';
const offer = String(s.comeBackOffer || '').trim();
const link = String(s.bookingLink || '').trim();
const linkLine = link ? `You can book your next visit here: ${link}` : 'Just reply to this email and we will find you a time.';
const T = [
  [`We miss you, ${first}`, `Hi ${first},\n\nIt has been a little while since your ${service} with ${biz}, and we wanted to check in. How has everything been since then?\n\n${linkLine}`],
  [`A little something for your next visit, ${first}`, `Hi ${first},\n\nWe would love to see you again. ${offer ? offer + ' is waiting for you whenever you are ready.' : 'Whenever you are ready, we have a spot for you.'}\n\n${linkLine}`],
  [`Can I ask you something, ${first}?`, `Hi ${first},\n\nWe have not seen you in a while, and your opinion matters to us. Was there anything we could have done better after your ${service}? A one-line reply helps more than you think.\n\n${linkLine}`],
];
let [subject, body] = T[c.isLast ? 2 : Math.min(c.stageIndex, 1)];
let usedAI = false;
const ai = String($json.text || '').trim();
if (ai) {
  const clean = ai.replace(/```[a-z]*/gi, '').replace(/\*\*/g, '').trim();
  const m = clean.match(/^\s*subject\s*:\s*(.+)\r?\n([\s\S]+)$/i);
  if (m) {
    const sub = m[1].trim().replace(/^["']|["']$/g, ''), bod = m[2].trim();
    const placeholder = /\[[^\]]{2,30}\]|\{\{|\}\}/.test(sub + bod);
    const madeUpDeal = !offer && /\d+\s*%|\$\s*\d|free\b|discount/i.test(bod);  // never promise a deal the owner did not set
    if (!placeholder && !madeUpDeal && sub.length >= 3 && sub.length <= 120 && bod.length >= 40 && bod.length <= 1500) { subject = sub; body = bod; usedAI = true; }
  }
}
body = body.replace(/\n\s*(best|best regards|kind regards|warm regards|regards|thanks|thank you|cheers|sincerely|talk soon)[,!.]?\s*(\n[\s\S]{0,80})?$/i, '').trim();
{                                                                       // and a closing like "Have a great week,\nSam"
  const L = body.split('\n'); while (L.length && !L[L.length - 1].trim()) L.pop();
  const last = (L[L.length - 1] || '').trim();
  if (last && last.length <= 40 && !/[.?!:]$/.test(last) && last.split(/\s+/).length <= 4) {
    let i = L.length - 2; while (i >= 0 && !L[i].trim()) i--;
    if (i >= 0 && /,\s*$/.test(L[i]) && L[i].trim().length <= 60) L.splice(i);
  }
  body = L.join('\n').trim();
}
// A blank line after the greeting, whatever the AI did.
body = body.replace(/^(\s*(hi|hello|hey|dear)\b[^\n]{0,60},)[ \t]*\n(?!\s*\n)/i, '$1\n\n');
body = body.replace(/\s*\u2014\s*/g, ', ');                                // no em dashes
const sign = `\n\nWarmly,\n${you}${s.businessName ? '\n' + s.businessName : ''}`;
const optOut = `\n\nRather not get these? Just reply STOP.`;
return { json: { row_number: c.row_number, to: c.email, name: c.name, subject, body: body + sign + optOut, usedAI,
  stage: c.stage, daysAway: c.daysAway, today: c.today } };

// One summary email to the owner: who got a win-back message today, and which one.
const sent = $('Build Email').all().map(i => i.json);
// Each item that came out of Send Email points back (pairedItem) to the email it sent.
const ok = new Set($input.all().map(i => { const p = Array.isArray(i.pairedItem) ? i.pairedItem[0] : i.pairedItem; return p ? p.item : -1; }));
const rows = sent.filter((r, idx) => ok.has(idx));
const lines = rows.map(r => `- ${r.name || r.to} (${r.to}): ${r.stage}-day message, away ${r.daysAway} days${r.usedAI ? '' : ' (template)'}`);
return [{ json: {
  subject: `Win-back: ${rows.length} past customer${rows.length === 1 ? '' : 's'} contacted today`,
  body: `Your customer re-engagement ran today.\n\n${lines.join('\n') || 'Nobody was due.'}\n\nWhen someone replies you get an email right away. When they visit again, update their Last Visit and the count starts over.`,
} }];
